    message = f'HOLD: {reason}'
    try:
        r = requests.post(f'{BASE}/owner/notify', json={'message': message}, timeout=10)
        if not (200 <= r.status_code < 300):
            result.update(status='hold_notification_failed', detail=f'{message}; notify returned HTTP {r.status_code}')
        else:
            result.update(status='held', detail=message)
    except Exception as e:
        result.update(status='hold_notification_failed', detail=f'{message}; notify failed: {type(e).__name__}: {e}')

try:
    r = requests.get(f'{BASE}/batches/last', timeout=10)
    if not (200 <= r.status_code < 300):
        raise ValueError(f'GET /batches/last returned HTTP {r.status_code}')
    try:
        last = r.json()
    except Exception as e:
        raise ValueError(f'GET /batches/last did not return valid JSON ({type(e).__name__})')
    if not isinstance(last, dict) or set(last) != {'last_seq'}:
        raise ValueError(f'GET /batches/last JSON did not have exactly the key last_seq: {last!r}')
    n = last['last_seq']
    if isinstance(n, bool) or not isinstance(n, int) or n < 0:
        raise ValueError(f'last_seq was not a nonnegative integer: {n!r}')

    r = requests.get(f'{BASE}/orders', params={'after': n}, timeout=10)
    if not (200 <= r.status_code < 300):
        raise ValueError(f'GET /orders?after={n} returned HTTP {r.status_code}')
    try:
        orders = r.json()
    except Exception as e:
        raise ValueError(f'GET /orders?after={n} did not return valid JSON ({type(e).__name__})')
    if not isinstance(orders, list):
        raise ValueError(f'orders response was not a JSON array: {type(orders).__name__}')
    if len(orders) > 200:
        raise ValueError(f'orders response contained {len(orders)} items, exceeding the limit of 200')
    if not orders:
        result.update(status='no_orders', detail=f'No orders after seq {n}; no action taken')
    else:
        expected = {'seq', 'date', 'region', 'units', 'unit_price_cents'}
        prev = n
        seen = set()
        region_totals = defaultdict(int)
        total_units = 0
        total_revenue = 0
        date_pattern = re.compile(r'^\d{4}-\d{2}-\d{2}$')
        for i, o in enumerate(orders):
            if not isinstance(o, dict) or set(o) != expected:
                raise ValueError(f'order index {i} did not contain exactly the required keys')
            for k in ('seq', 'units', 'unit_price_cents'):
                if isinstance(o[k], bool) or not isinstance(o[k], int):
                    raise ValueError(f'order index {i} field {k} was not an integer')
            if o['seq'] <= n:
                raise ValueError(f'order index {i} seq {o["seq"]} was not greater than last_seq {n}')
            if o['seq'] in seen or o['seq'] <= prev:
                raise ValueError(f'order seq values were not unique and strictly increasing at index {i} (seq {o["seq"]})')
            if not isinstance(o['date'], str) or not date_pattern.fullmatch(o['date']):
                raise ValueError(f'order index {i} date was not exactly YYYY-MM-DD')
            try:
                datetime.strptime(o['date'], '%Y-%m-%d')
            except ValueError:
                raise ValueError(f'order index {i} date was not a real calendar date: {o["date"]!r}')
            if not isinstance(o['region'], str):
                raise ValueError(f'order index {i} region was not a string')
            seen.add(o['seq']); prev = o['seq']
            revenue = o['units'] * o['unit_price_cents']
            total_units += o['units']
            total_revenue += revenue
            region_totals[o['region']] += revenue

        payload = {
            'batch_start_seq': orders[0]['seq'],
            'batch_end_seq': orders[-1]['seq'],
            'order_count': len(orders),
            'total_units': total_units,
            'total_revenue_cents': total_revenue,
            'revenue_by_region_cents': dict(region_totals),
        }
        # This POST is intentionally attempted at most once.
        try:
            pr = requests.post(f'{BASE}/batches', json=payload, timeout=10)
        except Exception as e:
            notify_hold(f'POST /batches had an ambiguous network result ({type(e).__name__}: {e}); it was not retried')
        else:
            if not (200 <= pr.status_code < 300):
                notify_hold(f'POST /batches returned HTTP {pr.status_code}; it was not retried')
